//! Keypad input, IO 0x130-0x133 (gbatek: GBA Keypad Input).

use crate::io::merge;

const KEYINPUT: u32 = 0x130; // key status, active low
const KEYCNT: u32 = 0x132; // key interrupt control

/// The 10 key bits (A, B, Select, Start, Right, Left, Up, Down, R, L).
const KEY_BITS: u16 = 0x03FF;

pub struct Keypad {
    /// Pressed keys, active high, in ABI bit order (same order as KEYINPUT).
    pressed_keys: u16,
    key_control: u16,
}

impl Keypad {
    pub fn new() -> Self {
        Keypad { pressed_keys: 0, key_control: 0 }
    }

    /// Latch the host key state (active high); it holds until the next call.
    pub fn set_keys(&mut self, pressed_keys: u32) {
        self.pressed_keys = pressed_keys as u16 & KEY_BITS;
    }

    pub fn io_read16(&mut self, offset: u32) -> u16 {
        match offset {
            KEYINPUT => !self.pressed_keys & KEY_BITS,
            KEYCNT => self.key_control,
            _ => 0,
        }
    }

    pub fn io_write16(&mut self, offset: u32, value: u16, mask: u16) {
        // ponytail: KEYCNT is stored but the keypad IRQ is not raised yet.
        if offset == KEYCNT {
            self.key_control = merge(self.key_control, value, mask);
        }
    }
}
//! IO register dispatch: maps an offset inside 0x04000000 to the component that owns it
//! (gbatek: GBA I/O Map).
//!
//! Every owner exposes `io_read16(offset) -> u16` and `io_write16(offset, value, mask)`, where
//! `offset` is the halfword-aligned offset from 0x04000000 and `mask` marks the bytes really written
//! (0x00FF / 0xFF00 for 8-bit writes, 0xFFFF otherwise). 8- and 32-bit accesses are split or merged
//! here, so owners only ever see halfwords. The mask matters for registers where a read-modify-write
//! would be wrong: IF acknowledge, HALTCNT, the sound FIFOs, write-only registers.

use crate::bus::Bus;

/// Owner ranges, inclusive (PLAN.md section 2).
const PPU_RANGE: (u32, u32) = (0x000, 0x05F);
const APU_RANGE: (u32, u32) = (0x060, 0x0AF);
const DMA_RANGE: (u32, u32) = (0x0B0, 0x0DF);
const TIMER_RANGE: (u32, u32) = (0x100, 0x10F);
const SERIAL_LOW_RANGE: (u32, u32) = (0x120, 0x12F);
const KEYPAD_RANGE: (u32, u32) = (0x130, 0x133);
const SERIAL_HIGH_RANGE: (u32, u32) = (0x134, 0x15F);
const SYSTEM_RANGE: (u32, u32) = (crate::irq::IO_START, crate::irq::IO_END);

/// Replace only the masked bits of `old` with those of `new`. Shared helper for every owner.
pub fn merge(old: u16, new: u16, mask: u16) -> u16 {
    (old & !mask) | (new & mask)
}

fn in_range(offset: u32, range: (u32, u32)) -> bool {
    offset >= range.0 && offset <= range.1
}

/// Plain halfword storage for a block of IO registers starting at `base`. Stubs and simple
/// owners use it so a write reads back unchanged.
pub struct PlainRegisters<const HALFWORDS: usize> {
    base: u32,
    values: [u16; HALFWORDS],
}

impl<const HALFWORDS: usize> PlainRegisters<HALFWORDS> {
    pub fn new(base: u32) -> Self {
        PlainRegisters { base, values: [0; HALFWORDS] }
    }

    pub fn read(&self, offset: u32) -> u16 {
        self.values[((offset - self.base) / 2) as usize]
    }

    pub fn write(&mut self, offset: u32, value: u16, mask: u16) {
        let slot = &mut self.values[((offset - self.base) / 2) as usize];
        *slot = merge(*slot, value, mask);
    }
}

/// Serial port registers 0x120-0x15F (SIOCNT, SIODATA, RCNT, JOY_*): plain storage, never connected.
pub struct SerialStub {
    registers: PlainRegisters<0x20>,
}

impl SerialStub {
    pub fn new() -> Self {
        SerialStub { registers: PlainRegisters::new(SERIAL_LOW_RANGE.0) }
    }

    pub fn io_read16(&mut self, offset: u32) -> u16 {
        self.registers.read(offset)
    }

    pub fn io_write16(&mut self, offset: u32, value: u16, mask: u16) {
        self.registers.write(offset, value, mask)
    }
}

impl Bus {
    /// Route a halfword read to its owner. Unmapped offsets read as 0.
    // ponytail: unmapped reads return 0, not open bus; Phase 2 integrator adds open bus.
    fn io_dispatch_read16(&mut self, offset: u32) -> u16 {
        if in_range(offset, PPU_RANGE) {
            self.ppu.io_read16(offset)
        } else if in_range(offset, APU_RANGE) {
            self.apu.io_read16(offset)
        } else if in_range(offset, DMA_RANGE) {
            self.dma.io_read16(offset)
        } else if in_range(offset, TIMER_RANGE) {
            self.timers.io_read16(offset)
        } else if in_range(offset, KEYPAD_RANGE) {
            self.keypad.io_read16(offset)
        } else if in_range(offset, SERIAL_LOW_RANGE) || in_range(offset, SERIAL_HIGH_RANGE) {
            self.serial.io_read16(offset)
        } else if in_range(offset, SYSTEM_RANGE) {
            self.irq.io_read16(offset)
        } else {
            0
        }
    }

    /// Route a halfword write (with byte mask) to its owner. Unmapped offsets are ignored.
    fn io_dispatch_write16(&mut self, offset: u32, value: u16, mask: u16) {
        if in_range(offset, PPU_RANGE) {
            self.ppu.io_write16(offset, value, mask)
        } else if in_range(offset, APU_RANGE) {
            self.apu.io_write16(offset, value, mask)
        } else if in_range(offset, DMA_RANGE) {
            self.dma.io_write16(offset, value, mask)
        } else if in_range(offset, TIMER_RANGE) {
            self.timers.io_write16(offset, value, mask)
        } else if in_range(offset, KEYPAD_RANGE) {
            self.keypad.io_write16(offset, value, mask)
        } else if in_range(offset, SERIAL_LOW_RANGE) || in_range(offset, SERIAL_HIGH_RANGE) {
            self.serial.io_write16(offset, value, mask)
        } else if in_range(offset, SYSTEM_RANGE) {
            self.irq.io_write16(offset, value, mask)
        }
    }

    pub fn io_read8(&mut self, offset: u32) -> u8 {
        let halfword = self.io_dispatch_read16(offset & !1);
        (halfword >> ((offset & 1) * 8)) as u8
    }

    pub fn io_read16(&mut self, offset: u32) -> u16 {
        self.io_dispatch_read16(offset & !1)
    }

    pub fn io_read32(&mut self, offset: u32) -> u32 {
        let aligned = offset & !3;
        let low = self.io_dispatch_read16(aligned) as u32;
        let high = self.io_dispatch_read16(aligned + 2) as u32;
        low | (high << 16)
    }

    pub fn io_write8(&mut self, offset: u32, value: u8) {
        let shift = (offset & 1) * 8;
        let halfword = (value as u16) << shift;
        let mask = 0xFFu16 << shift;
        self.io_dispatch_write16(offset & !1, halfword, mask);
    }

    pub fn io_write16(&mut self, offset: u32, value: u16) {
        self.io_dispatch_write16(offset & !1, value, 0xFFFF);
    }

    pub fn io_write32(&mut self, offset: u32, value: u32) {
        let aligned = offset & !3;
        self.io_dispatch_write16(aligned, value as u16, 0xFFFF);
        self.io_dispatch_write16(aligned + 2, (value >> 16) as u16, 0xFFFF);
    }
}
//! The whole machine: CPU plus bus (which owns every other component), and the frame loop.
//!
//! Events between components (PPU -> DMA, timers -> APU, APU -> DMA) are plain method calls here,
//! so no component holds a reference to another.

use crate::bus::Bus;
use crate::cpu::Cpu;
use crate::dma;
use crate::ppu::CYCLES_PER_LINE;
use crate::scheduler::Scheduler;

/// 228 lines x 1232 cycles (gbatek: LCD Dimensions and Timings).
pub const CYCLES_PER_FRAME: u32 = 280_896;

/// Scanline at whose start `run_frame` returns. 0 = each frame runs lines 0..227 (drawing, then
/// all of VBlank); 160 would end at VBlank start. Measured against Mesen2 via the grader (see
/// NOTES.md, 2026-11-05): a key set before frame N first shows in frame N+1 on tonc key-demo,
/// which polls keys at VBlank, so the reference's frame includes the VBlank after the picture.
pub const FRAME_END_LINE: u32 = 0;

pub struct Gba {
    pub cpu: Cpu,
    pub bus: Bus,
    pub scheduler: Scheduler,
    /// Cycles left before the current frame ends; overshoot carries into the next frame.
    cycles_until_frame_end: i64,
}

impl Gba {
    /// Power-on state with `rom` inserted. The CPU starts at the BIOS reset vector.
    pub fn new(rom: &[u8]) -> Self {
        let first_frame_cycles = match FRAME_END_LINE * CYCLES_PER_LINE {
            0 => CYCLES_PER_FRAME,
            cycles => cycles,
        };
        Gba {
            cpu: Cpu::new(),
            bus: Bus::new(rom),
            scheduler: Scheduler::new(),
            cycles_until_frame_end: first_frame_cycles as i64,
        }
    }

    /// Latch the host key state (ABI bit order, active high).
    pub fn set_keys(&mut self, pressed_keys: u32) {
        self.bus.keypad.set_keys(pressed_keys);
    }

    /// Run until the frame boundary (see `FRAME_END_LINE`).
    pub fn run_frame(&mut self) {
        while self.cycles_until_frame_end > 0 {
            let mut cycles = self.cpu.step(&mut self.bus);
            cycles += dma::run_pending_transfers(&mut self.bus);
            self.advance_components(cycles);
            self.cycles_until_frame_end -= cycles as i64;
        }
        self.cycles_until_frame_end += CYCLES_PER_FRAME as i64;
    }

    /// Advance PPU, timers and APU by `cycles` and route their events.
    fn advance_components(&mut self, cycles: u32) {
        let bus = &mut self.bus;
        self.scheduler.advance(cycles);

        let ppu_events = bus.ppu.step(cycles, &mut bus.irq);
        if ppu_events.hblank_started {
            bus.dma.notify_hblank();
        }
        if ppu_events.vblank_started {
            bus.dma.notify_vblank();
        }

        let overflowed_timers = bus.timers.step(cycles, &mut bus.irq);
        for timer_index in 0..4 {
            if overflowed_timers & (1 << timer_index) == 0 {
                continue;
            }
            let fifo_requests = bus.apu.on_timer_overflow(timer_index);
            for fifo_index in 0..2 {
                if fifo_requests & (1 << fifo_index) != 0 {
                    bus.dma.notify_fifo_request(fifo_index);
                }
            }
        }

        bus.apu.step(cycles);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn frames_keep_line_timing_aligned() {
        let mut gba = Gba::new(&[]);
        gba.run_frame();
        assert_eq!(gba.bus.ppu.vcount as u32, FRAME_END_LINE % 228);
        let after_first = gba.scheduler.total_cycles;
        gba.run_frame();
        assert_eq!(gba.scheduler.total_cycles - after_first, CYCLES_PER_FRAME as u64);
        assert_eq!(gba.bus.ppu.vcount as u32, FRAME_END_LINE % 228);
    }

    #[test]
    fn vblank_irq_is_requested_when_enabled() {
        let mut gba = Gba::new(&[]);
        gba.bus.write16(0x0400_0004, 1 << 3); // DISPSTAT: VBlank IRQ enable
        gba.run_frame();
        gba.run_frame();
        assert_ne!(gba.bus.irq.interrupt_flags & 1, 0);
    }
}

//! System bus: memory map, region dispatch and access-cycle costs (gbatek: GBA Memory Map).
//!
//! The CPU only ever talks to the bus. Every access adds its cycle cost to `access_cycles`,
//! which the CPU drains with `take_access_cycles()` to report how long a step took.

use crate::apu::Apu;
use crate::cart::Cart;
use crate::dma::Dma;
use crate::io::SerialStub;
use crate::irq::Irq;
use crate::keypad::Keypad;
use crate::ppu::Ppu;
use crate::timer::Timers;

/// The 16 KiB BIOS stub supplied by the benchmark, mapped at 0x00000000.
static BIOS: &[u8; BIOS_SIZE] = include_bytes!("../assets/gba_bios_stub.bin");

pub const BIOS_SIZE: usize = 0x4000;
pub const EWRAM_SIZE: usize = 0x40000; // on-board work RAM, 256 KiB
pub const IWRAM_SIZE: usize = 0x8000; // on-chip work RAM, 32 KiB

/// Access width, used to pick the cycle cost.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Width {
    Byte,
    Halfword,
    Word,
}

/// Memory regions, selected by address bits 24-27.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Region {
    Bios,
    Ewram,
    Iwram,
    Io,
    Palette,
    Vram,
    Oam,
    Rom,
    Sram,
    Unmapped,
}

fn region_of(address: u32) -> Region {
    match address >> 24 {
        0x00 => Region::Bios,
        0x02 => Region::Ewram,
        0x03 => Region::Iwram,
        0x04 => Region::Io,
        0x05 => Region::Palette,
        0x06 => Region::Vram,
        0x07 => Region::Oam,
        0x08..=0x0D => Region::Rom,
        0x0E | 0x0F => Region::Sram,
        _ => Region::Unmapped,
    }
}

/// Cycle cost with default wait states (gbatek: GBA Memory Map, "Address Bus Width and CPU
/// Read/Write Access Widths").
// ponytail: fixed default wait states, no WAITCNT, no sequential/non-sequential split, no
// video-memory contention; Phase 2/5 wire WAITCNT and prefetch in here.
fn access_cost(region: Region, width: Width) -> u32 {
    let is_word = width == Width::Word;
    match region {
        Region::Bios | Region::Iwram | Region::Io | Region::Oam | Region::Unmapped => 1,
        Region::Ewram => if is_word { 6 } else { 3 },
        Region::Palette | Region::Vram => if is_word { 2 } else { 1 },
        Region::Rom => if is_word { 8 } else { 5 },
        Region::Sram => 5,
    }
}

/// Offset into VRAM: 96 KiB mirrored in 128 KiB steps, the upper 32 KiB mirroring 0x10000-0x17FFF.
fn vram_offset(address: u32) -> usize {
    let offset = address & 0x1FFFF;
    (if offset >= 0x18000 { offset - 0x8000 } else { offset }) as usize
}

fn read_le16(memory: &[u8], offset: usize) -> u16 {
    u16::from_le_bytes([memory[offset], memory[offset + 1]])
}

fn read_le32(memory: &[u8], offset: usize) -> u32 {
    u32::from_le_bytes([memory[offset], memory[offset + 1], memory[offset + 2], memory[offset + 3]])
}

fn write_le16(memory: &mut [u8], offset: usize, value: u16) {
    memory[offset..offset + 2].copy_from_slice(&value.to_le_bytes());
}

fn write_le32(memory: &mut [u8], offset: usize, value: u32) {
    memory[offset..offset + 4].copy_from_slice(&value.to_le_bytes());
}

pub struct Bus {
    pub ewram: Vec<u8>,
    pub iwram: Vec<u8>,
    pub ppu: Ppu, // also owns palette RAM, VRAM and OAM
    pub apu: Apu,
    pub dma: Dma,
    pub timers: Timers,
    pub keypad: Keypad,
    pub serial: SerialStub,
    pub irq: Irq,
    pub cart: Cart,
    /// Cycles spent on accesses since the last `take_access_cycles()`.
    pub access_cycles: u32,
}

impl Bus {
    pub fn new(rom: &[u8]) -> Self {
        Bus {
            ewram: vec![0; EWRAM_SIZE],
            iwram: vec![0; IWRAM_SIZE],
            ppu: Ppu::new(),
            apu: Apu::new(),
            dma: Dma::new(),
            timers: Timers::new(),
            keypad: Keypad::new(),
            serial: SerialStub::new(),
            irq: Irq::new(),
            cart: Cart::new(rom),
            access_cycles: 0,
        }
    }

    /// Return and reset the cycles spent on bus accesses.
    pub fn take_access_cycles(&mut self) -> u32 {
        std::mem::take(&mut self.access_cycles)
    }

    fn charge(&mut self, address: u32, width: Width) -> Region {
        let region = region_of(address);
        self.access_cycles += access_cost(region, width);
        region
    }

    pub fn read8(&mut self, address: u32) -> u8 {
        match self.charge(address, Width::Byte) {
            Region::Bios => bios_read(address, 1) as u8,
            Region::Ewram => self.ewram[(address as usize) & (EWRAM_SIZE - 1)],
            Region::Iwram => self.iwram[(address as usize) & (IWRAM_SIZE - 1)],
            Region::Io => self.io_read8(io_offset(address)),
            Region::Palette => self.ppu.palette[(address & 0x3FF) as usize],
            Region::Vram => self.ppu.vram[vram_offset(address)],
            Region::Oam => self.ppu.oam[(address & 0x3FF) as usize],
            Region::Rom => self.cart.rom_read8(address),
            Region::Sram => self.cart.sram_read8(address),
            Region::Unmapped => 0,
        }
    }

    pub fn read16(&mut self, address: u32) -> u16 {
        // ponytail: misaligned addresses are force-aligned; rotation of misaligned reads belongs to the CPU.
        let address = address & !1;
        match self.charge(address, Width::Halfword) {
            Region::Bios => bios_read(address, 2) as u16,
            Region::Ewram => read_le16(&self.ewram, (address as usize) & (EWRAM_SIZE - 1)),
            Region::Iwram => read_le16(&self.iwram, (address as usize) & (IWRAM_SIZE - 1)),
            Region::Io => self.io_read16(io_offset(address)),
            Region::Palette => read_le16(&self.ppu.palette, (address & 0x3FF) as usize),
            Region::Vram => read_le16(&self.ppu.vram, vram_offset(address)),
            Region::Oam => read_le16(&self.ppu.oam, (address & 0x3FF) as usize),
            Region::Rom => self.cart.rom_read16(address),
            Region::Sram => self.cart.sram_read8(address) as u16 * 0x0101,
            Region::Unmapped => 0,
        }
    }

    pub fn read32(&mut self, address: u32) -> u32 {
        let address = address & !3;
        match self.charge(address, Width::Word) {
            Region::Bios => bios_read(address, 4),
            Region::Ewram => read_le32(&self.ewram, (address as usize) & (EWRAM_SIZE - 1)),
            Region::Iwram => read_le32(&self.iwram, (address as usize) & (IWRAM_SIZE - 1)),
            Region::Io => self.io_read32(io_offset(address)),
            Region::Palette => read_le32(&self.ppu.palette, (address & 0x3FF) as usize),
            Region::Vram => read_le32(&self.ppu.vram, vram_offset(address)),
            Region::Oam => read_le32(&self.ppu.oam, (address & 0x3FF) as usize),
            Region::Rom => {
                let low = self.cart.rom_read16(address) as u32;
                let high = self.cart.rom_read16(address + 2) as u32;
                low | (high << 16)
            }
            Region::Sram => self.cart.sram_read8(address) as u32 * 0x0101_0101,
            Region::Unmapped => 0,
        }
    }

    pub fn write8(&mut self, address: u32, value: u8) {
        match self.charge(address, Width::Byte) {
            Region::Ewram => self.ewram[(address as usize) & (EWRAM_SIZE - 1)] = value,
            Region::Iwram => self.iwram[(address as usize) & (IWRAM_SIZE - 1)] = value,
            Region::Io => self.io_write8(io_offset(address), value),
            // Palette and VRAM have a 16-bit data bus: a byte write lands in both halves.
            // ponytail: VRAM byte writes into the OBJ area should be ignored; mode-dependent, left to the PPU agent.
            Region::Palette => {
                write_le16(&mut self.ppu.palette, (address & 0x3FE) as usize, value as u16 * 0x0101)
            }
            Region::Vram => {
                write_le16(&mut self.ppu.vram, vram_offset(address & !1), value as u16 * 0x0101)
            }
            Region::Oam => {} // OAM ignores 8-bit writes
            Region::Sram => self.cart.sram_write8(address, value),
            Region::Bios | Region::Rom | Region::Unmapped => {}
        }
    }

    pub fn write16(&mut self, address: u32, value: u16) {
        let address = address & !1;
        match self.charge(address, Width::Halfword) {
            Region::Ewram => write_le16(&mut self.ewram, (address as usize) & (EWRAM_SIZE - 1), value),
            Region::Iwram => write_le16(&mut self.iwram, (address as usize) & (IWRAM_SIZE - 1), value),
            Region::Io => self.io_write16(io_offset(address), value),
            Region::Palette => write_le16(&mut self.ppu.palette, (address & 0x3FF) as usize, value),
            Region::Vram => write_le16(&mut self.ppu.vram, vram_offset(address), value),
            Region::Oam => write_le16(&mut self.ppu.oam, (address & 0x3FF) as usize, value),
            Region::Sram => self.cart.sram_write8(address, value as u8),
            Region::Rom => self.cart.rom_write16(address, value),
            Region::Bios | Region::Unmapped => {}
        }
    }

    pub fn write32(&mut self, address: u32, value: u32) {
        let address = address & !3;
        match self.charge(address, Width::Word) {
            Region::Ewram => write_le32(&mut self.ewram, (address as usize) & (EWRAM_SIZE - 1), value),
            Region::Iwram => write_le32(&mut self.iwram, (address as usize) & (IWRAM_SIZE - 1), value),
            Region::Io => self.io_write32(io_offset(address), value),
            Region::Palette => write_le32(&mut self.ppu.palette, (address & 0x3FF) as usize, value),
            Region::Vram => write_le32(&mut self.ppu.vram, vram_offset(address), value),
            Region::Oam => write_le32(&mut self.ppu.oam, (address & 0x3FF) as usize, value),
            Region::Sram => self.cart.sram_write8(address, value as u8),
            Region::Rom => {
                self.cart.rom_write16(address, value as u16);
                self.cart.rom_write16(address + 2, (value >> 16) as u16);
            }
            Region::Bios | Region::Unmapped => {}
        }
    }
}

/// IO offset from 0x04000000. Only 0x000-0x3FF and 0x800-0x803 are registers; the rest reads 0.
fn io_offset(address: u32) -> u32 {
    let offset = address & 0x00FF_FFFF;
    if offset < 0x400 || (0x800..0x804).contains(&offset) {
        offset
    } else {
        0xFFFF_FFFF // no owner: io.rs treats it as unmapped
    }
}

/// Little-endian read of `size` bytes from the BIOS. Outside 0x0000-0x3FFF reads 0.
// ponytail: no BIOS read protection (last-fetched-opcode value); add when a test reads BIOS from ROM code.
fn bios_read(address: u32, size: usize) -> u32 {
    let offset = address as usize;
    if offset + size > BIOS_SIZE {
        return 0;
    }
    (0..size).fold(0, |value, i| value | (BIOS[offset + i] as u32) << (8 * i))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn round_trip_every_width_in_ram_regions() {
        let mut bus = Bus::new(&[]);
        for base in [0x0200_0000u32, 0x0300_0000, 0x0500_0000, 0x0600_0000, 0x0700_0000] {
            bus.write32(base + 0x10, 0xDEAD_BEEF);
            assert_eq!(bus.read32(base + 0x10), 0xDEAD_BEEF, "word at {base:#x}");
            assert_eq!(bus.read16(base + 0x12), 0xDEAD, "high halfword at {base:#x}");
            assert_eq!(bus.read8(base + 0x10), 0xEF, "low byte at {base:#x}");

            bus.write16(base + 0x20, 0x1234);
            assert_eq!(bus.read16(base + 0x20), 0x1234, "halfword at {base:#x}");
        }
        for base in [0x0200_0000u32, 0x0300_0000] {
            bus.write8(base + 0x31, 0xAB);
            assert_eq!(bus.read8(base + 0x31), 0xAB, "byte at {base:#x}");
        }
        // Mirrors: EWRAM every 256 KiB, IWRAM every 32 KiB.
        assert_eq!(bus.read32(0x0204_0010), 0xDEAD_BEEF);
        assert_eq!(bus.read32(0x0300_8010), 0xDEAD_BEEF);
    }

    #[test]
    fn bios_is_mapped_and_read_only() {
        let mut bus = Bus::new(&[]);
        let reset_vector = bus.read32(0);
        assert_eq!(reset_vector, u32::from_le_bytes([BIOS[0], BIOS[1], BIOS[2], BIOS[3]]));
        bus.write32(0, 0);
        assert_eq!(bus.read32(0), reset_vector);
    }

    #[test]
    fn io_byte_write_acknowledges_only_its_own_if_bits() {
        let mut bus = Bus::new(&[]);
        bus.irq.interrupt_flags = 0x0101;
        bus.write8(0x0400_0202, 0x01); // acknowledge bit 0 only
        assert_eq!(bus.read16(0x0400_0202), 0x0100);
        bus.write32(0x0400_0200, 0x0000_3FFF); // IE = all, IF write of 0 clears nothing
        assert_eq!(bus.read32(0x0400_0200), 0x0100_3FFF);
    }

    #[test]
    fn access_cycles_follow_default_wait_states() {
        let mut bus = Bus::new(&[]);
        bus.read32(0x0200_0000);
        assert_eq!(bus.take_access_cycles(), 6);
        bus.read16(0x0800_0000);
        assert_eq!(bus.take_access_cycles(), 5);
    }
}
//! gba_emu: an original Game Boy Advance emulator.
//!
//! This file only holds the 10 C-ABI exports from `gba-eval/spec/ABI.md`, as thin wrappers over a
//! single global `Gba`. The wasm build has no imports: no printing, no threads, no filesystem.

pub mod apu;
pub mod bus;
pub mod cart;
pub mod cpu;
pub mod dma;
pub mod gba;
pub mod io;
pub mod irq;
pub mod keypad;
pub mod ppu;
pub mod scheduler;
pub mod timer;

use std::ptr::addr_of_mut;

use cart::MAX_ROM_SIZE;
use gba::Gba;
use ppu::{SCREEN_HEIGHT, SCREEN_WIDTH};

const FRAMEBUFFER_PIXELS: usize = SCREEN_WIDTH * SCREEN_HEIGHT;
/// Room for several frames of stereo pairs at the highest rate (262144 Hz ~ 4390 pairs/frame).
const AUDIO_BUFFER_PAIRS: usize = 1 << 15;

/// Host-visible state. The buffers live here, outside `Gba`, so their pointers stay valid
/// across `emu_load_rom` / `emu_reset`.
struct Emulator {
    rom_buffer: Vec<u8>,
    rom_length: usize,
    gba: Option<Box<Gba>>,
    framebuffer: Vec<u32>,
    audio_buffer: Vec<i16>,
}

static mut EMULATOR: Option<Emulator> = None;

/// The global emulator, created on first use.
fn emulator() -> &'static mut Emulator {
    // SAFETY: the ABI is single-threaded (wasm, no threads) and no export re-enters another,
    // so there is never more than one live reference.
    unsafe {
        (*addr_of_mut!(EMULATOR)).get_or_insert_with(|| Emulator {
            rom_buffer: vec![0; MAX_ROM_SIZE],
            rom_length: 0,
            gba: None,
            framebuffer: vec![0xFF00_0000; FRAMEBUFFER_PIXELS],
            audio_buffer: vec![0; AUDIO_BUFFER_PAIRS * 2],
        })
    }
}

impl Emulator {
    /// Power on with the ROM currently in the buffer; the same path serves load and reset.
    fn power_on(&mut self) {
        self.gba = Some(Box::new(Gba::new(&self.rom_buffer[..self.rom_length])));
        self.framebuffer.fill(0xFF00_0000);
    }
}

/// Set up global state. Returns 1 on success.
#[no_mangle]
pub extern "C" fn emu_init() -> i32 {
    emulator();
    1
}

/// Stable pointer to a 32 MiB buffer the host copies the ROM into before `emu_load_rom`.
#[no_mangle]
pub extern "C" fn emu_rom_buffer() -> *mut u8 {
    emulator().rom_buffer.as_mut_ptr()
}

/// Load the first `length` bytes of the ROM buffer and reset. Returns 1 on success.
#[no_mangle]
pub extern "C" fn emu_load_rom(length: i32) -> i32 {
    if length <= 0 || length as usize > MAX_ROM_SIZE {
        return 0;
    }
    let emulator = emulator();
    emulator.rom_length = length as usize;
    emulator.power_on();
    1
}

/// Reset to exactly the state `emu_load_rom` produces. Returns 0 if no ROM is loaded.
#[no_mangle]
pub extern "C" fn emu_reset() -> i32 {
    let emulator = emulator();
    if emulator.rom_length == 0 {
        return 0;
    }
    emulator.power_on();
    1
}

/// Latch the pressed keys (active high, bit 0 = A ... bit 9 = L).
#[no_mangle]
pub extern "C" fn emu_set_keys(keys: u32) {
    if let Some(gba) = emulator().gba.as_mut() {
        gba.set_keys(keys);
    }
}

/// Advance one frame (280,896 cycles) and publish its picture.
#[no_mangle]
pub extern "C" fn emu_run_frame() {
    let emulator = emulator();
    if let Some(gba) = emulator.gba.as_mut() {
        gba.run_frame();
        emulator.framebuffer.copy_from_slice(&gba.bus.ppu.framebuffer);
    }
}

/// 240x160 pixels, 0xAABBGGRR with alpha 0xFF.
#[no_mangle]
pub extern "C" fn emu_framebuffer() -> *mut u32 {
    emulator().framebuffer.as_mut_ptr()
}

/// Interleaved stereo i16 samples; valid count is the last `emu_audio_samples()` result.
#[no_mangle]
pub extern "C" fn emu_audio_buffer() -> *mut i16 {
    emulator().audio_buffer.as_mut_ptr()
}

/// Move the samples produced since the last call into the audio buffer; returns stereo pairs.
#[no_mangle]
pub extern "C" fn emu_audio_samples() -> i32 {
    let emulator = emulator();
    let Some(gba) = emulator.gba.as_mut() else { return 0 };
    let produced = &mut gba.bus.apu.samples;
    let copied = produced.len().min(emulator.audio_buffer.len());
    emulator.audio_buffer[..copied].copy_from_slice(&produced[..copied]);
    produced.clear();
    (copied / 2) as i32
}

/// Current output sample rate in Hz (32768 << SOUNDBIAS resolution).
#[no_mangle]
pub extern "C" fn emu_audio_rate() -> i32 {
    match emulator().gba.as_ref() {
        Some(gba) => gba.bus.apu.sample_rate() as i32,
        None => 32768,
    }
}
//! Interrupt controller and system-control IO range 0x200-0x804 (gbatek: GBA Interrupt Control).
//!
//! Any component raises an interrupt with `irq.request(IrqSource::...)`. Only the CPU consumes them,
//! through `pending()`.

use crate::io::{merge, PlainRegisters};

const IE: u32 = 0x200; // interrupt enable
const IF: u32 = 0x202; // interrupt request flags / acknowledge
const IME: u32 = 0x208; // interrupt master enable
const POSTFLG_HALTCNT: u32 = 0x300; // low byte POSTFLG (post-boot flag), high byte HALTCNT (low-power mode)

/// First IO offset owned by this module.
pub const IO_START: u32 = 0x200;
/// Last IO offset owned by this module (inclusive; 0x800 is the internal memory control register).
pub const IO_END: u32 = 0x804;

/// IE/IF bit 14-15 are unused.
const VALID_IRQ_BITS: u16 = 0x3FFF;

/// Interrupt sources, numbered by their IE/IF bit (gbatek: GBA Interrupt Control).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum IrqSource {
    VBlank = 0,
    HBlank = 1,
    VCounterMatch = 2,
    Timer0 = 3,
    Timer1 = 4,
    Timer2 = 5,
    Timer3 = 6,
    Serial = 7,
    Dma0 = 8,
    Dma1 = 9,
    Dma2 = 10,
    Dma3 = 11,
    Keypad = 12,
    GamePak = 13,
}

pub struct Irq {
    pub interrupt_enable: u16,
    pub interrupt_flags: u16,
    pub master_enable: bool,
    /// Set by a write to HALTCNT; the CPU clears it when an enabled interrupt wakes it.
    pub halt_requested: bool,
    /// Plain storage for the rest of 0x200-0x804 (WAITCNT, POSTFLG, ...), indexed by halfword.
    other_registers: PlainRegisters<{ ((IO_END - IO_START) / 2 + 1) as usize }>,
}

impl Irq {
    pub fn new() -> Self {
        Irq {
            interrupt_enable: 0,
            interrupt_flags: 0,
            master_enable: false,
            halt_requested: false,
            other_registers: PlainRegisters::new(IO_START),
        }
    }

    /// Raise an interrupt request flag in IF.
    pub fn request(&mut self, source: IrqSource) {
        self.interrupt_flags |= 1 << source as u16;
    }

    /// True when IME is on and some interrupt is both enabled (IE) and requested (IF).
    /// The CPSR I bit is the CPU's business.
    pub fn pending(&self) -> bool {
        self.master_enable && (self.interrupt_enable & self.interrupt_flags & VALID_IRQ_BITS) != 0
    }

    pub fn io_read16(&mut self, offset: u32) -> u16 {
        match offset {
            IE => self.interrupt_enable,
            IF => self.interrupt_flags,
            IME => self.master_enable as u16,
            _ => self.other_registers.read(offset),
        }
    }

    /// `mask` marks the bytes actually written (0x00FF, 0xFF00 or 0xFFFF); see io.rs.
    pub fn io_write16(&mut self, offset: u32, value: u16, mask: u16) {
        let written = value & mask;
        match offset {
            IE => self.interrupt_enable = merge(self.interrupt_enable, value, mask) & VALID_IRQ_BITS,
            // Writing 1 to an IF bit acknowledges (clears) it.
            IF => self.interrupt_flags &= !written,
            IME => self.master_enable = merge(self.master_enable as u16, value, mask) & 1 != 0,
            _ => {
                if offset == POSTFLG_HALTCNT && mask & 0xFF00 != 0 {
                    // ponytail: HALTCNT bit 7 (stop mode) is treated as halt too; add stop when a ROM needs it.
                    self.halt_requested = true;
                }
                self.other_registers.write(offset, value, mask);
            }
        }
    }
}
