use crate::io::merge;

const KEYINPUT: u32 = 0x130; // key status, active low
const KEYCNT: u32 = 0x132; // key interrupt control

/// The 10 key bits (A, B, Select, Start, Right, Left, Up, Down, R, L).
const KEY_BITS: u16 = 0x03FF;

pub struct Keypad {
