    fn put_4bpp_dot(bus: &mut Bus, tile: u32, color_index: u16) {
        bus.write16(0x0600_0000 + tile * 32, color_index);
    }

    #[test]
    fn text_bg_scrolls_flips_and_selects_screen_blocks() {
        let mut bus = Bus::new(&[]);
        bus.write16(0x0500_0000 + (2 * 16 + 1) * 2, GREEN); // palette bank 2, colour 1
        put_4bpp_dot(&mut bus, 1, 1); // tile 1: dot (0,0) colour 1
        // BG0: 4bpp, char base 0, screen base 8 (0x4000), 512x256.
        bus.write16(0x0400_0008, (8 << 8) | (1 << 14));
        let screen_base = 0x0600_4000;
        // SC1 (right half), tile column 0, row 0: tile 1, palette bank 2, horizontal flip.
        bus.write16(screen_base + 0x800, 1 | (1 << 10) | (2 << 12));
        bus.write16(0x0400_0010, 256); // BG0HOFS: SC1 starts at the screen's left edge
        bus.write16(0x0400_0000, 0x0100); // mode 0, BG0 on
        bus.ppu.render_line(0);
        assert_eq!(pixel(&bus, 7, 0), bgr555_to_abgr8888(GREEN), "flipped dot lands at x=7");
        assert_eq!(pixel(&bus, 0, 0), BLACK);
        // Wraparound: HOFS 256+511 -> same tile one pixel to the right.
        bus.write16(0x0400_0010, 511);
        bus.ppu.render_line(0);
        assert_eq!(pixel(&bus, 8, 0), BLACK);
        assert_eq!(pixel(&bus, 0, 0), BLACK);
        // VOFS moves row 0 of the map to line 255-0 boundary: line 1 shows map row 1 -> empty.
        bus.write16(0x0400_0010, 256);
        bus.write16(0x0400_0012, 1);
        bus.ppu.render_line(0);
        assert_eq!(pixel(&bus, 7, 0), BLACK);
    }

